import { AfterViewInit, ChangeDetectorRef, Component, ElementRef, OnDestroy, OnInit, ViewChild, inject } from '@angular/core';
import { CurrencyPipe, DatePipe, DecimalPipe } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { FormArray, FormBuilder, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, RouterLink, ActivatedRoute } from '@angular/router';
import { API_URL, AuthService, CartService, Dashboard, Pagina, Pedido, Prato } from './core';
import type { Chart as ChartInstance } from 'chart.js';
import { FeedbackService } from './feedback';

@Component({standalone:true,imports:[CurrencyPipe],template:`
<section class="hero"><div class="hero-copy"><span class="eyebrow">SABOR QUE FAZ BEM</span><h1>Seu dia mais leve,<br><em>uma refeição por vez.</em></h1><p>Pratos fresquinhos, ingredientes selecionados e muito sabor para cuidar de você.</p><a href="#menu" class="button primary">Explorar cardápio <span>↓</span></a><div class="hero-proof"><span>✓ Ingredientes frescos</span><span>✓ Feito na hora</span></div></div><div class="hero-art"><div class="plate"><div class="plate-leaf">🥗</div><span class="art-tag">FRESCO & NATURAL</span></div><div class="float-note"><b>feito com carinho</b><small>todos os dias</small></div></div><div class="hero-stamp">BOM<br>& FIT</div></section>
<section id="menu" class="menu-section"><div class="section-heading"><div><span class="eyebrow">ESCOLHA O SEU FAVORITO</span><h2>Nosso cardápio</h2></div><p>Uma seleção especial para alimentar bem o seu dia.</p></div>
@if(erro){<div class="notice">{{erro}} <button (click)="carregar()">Tentar novamente</button></div>}
<div class="filters"><button [class.selected]="categoria===null" (click)="filtrar(null)">Todos</button>@for(c of categorias;track c.id){<button [class.selected]="categoria===c.id" (click)="filtrar(c.id)">{{c.nome}}</button>}</div>
@if(carregando){<div class="loading">Preparando o cardápio…</div>}@else if(pratos.length){<div class="dish-grid">@for(p of pratos;track p.id){<article class="dish-card"><div class="dish-photo" [class.no-photo]="!p.fotoUrl">@if(p.fotoUrl){<img [src]="p.fotoUrl" [alt]="p.nome"/>}@else{<span>🥑</span>}<span class="dish-badge">{{p.categoria}}</span></div><div class="dish-info"><div class="dish-title"><h3>{{p.nome}}</h3><strong>{{p.precoVenda|currency:'BRL'}}</strong></div><p>{{p.descricao}}</p><div class="dish-bottom"><small>◷ {{p.tempoPreparoMin}} min</small><button class="text-button" (click)="verDetalhe(p)">Detalhes</button><button class="add-button" (click)="adicionar(p)">Adicionar <span>＋</span></button></div></div></article>}</div>}@else{<div class="empty-state"><span>🍽️</span><h3>Cardápio sendo preparado</h3><p>Em instantes teremos novidades fresquinhas por aqui.</p></div>}@if(totalPaginas>1){<div class="pagination"><button class="button outline" [disabled]="pagina<=0" (click)="mudarPagina(-1)">← Anterior</button><span>Página {{pagina+1}} de {{totalPaginas}}</span><button class="button outline" [disabled]="pagina+1>=totalPaginas" (click)="mudarPagina(1)">Próxima →</button></div>}
</section>@if(pratoDetalhe){<div class="modal-backdrop" (click)="pratoDetalhe=null"><section class="detail-modal" role="dialog" aria-modal="true" [attr.aria-label]="'Detalhes de '+pratoDetalhe.nome" (click)="$event.stopPropagation()"><button class="modal-close" aria-label="Fechar" (click)="pratoDetalhe=null">×</button>@if(pratoDetalhe.fotoUrl){<img class="detail-photo" [src]="pratoDetalhe.fotoUrl" [alt]="pratoDetalhe.nome"/>}<span class="eyebrow">{{pratoDetalhe.categoria}}</span><h2>{{pratoDetalhe.nome}}</h2><p>{{pratoDetalhe.descricao}}</p><div class="detail-meta"><span>◷ {{pratoDetalhe.tempoPreparoMin}} min</span><strong>{{pratoDetalhe.precoVenda|currency:'BRL'}}</strong></div><button class="button primary full" (click)="adicionar(pratoDetalhe);pratoDetalhe=null">Adicionar ao carrinho</button></section></div>}<div class="callout"><span>🥬</span><div><b>Comer bem pode ser simples.</b><p>Ingredientes de qualidade, receitas equilibradas e sabor em cada detalhe.</p></div><span class="callout-heart">♥</span></div>
`})
export class HomePage implements OnInit {
  private http=inject(HttpClient); private cdr=inject(ChangeDetectorRef); cart=inject(CartService); router=inject(Router); auth=inject(AuthService);feedback=inject(FeedbackService);
  pratos:Prato[]=[]; categorias:{id:number;nome:string}[]=[]; categoria:number|null=null; pagina=0;totalPaginas=0;carregando=true; erro=''; pratoDetalhe:Prato|null=null;
  ngOnInit(){this.http.get<{id:number;nome:string}[]>(`${API_URL}/cardapio/categorias`).subscribe({next:v=>{this.categorias=v;this.cdr.detectChanges();},error:()=>{}});this.carregar();}
  carregar(){this.carregando=true;this.erro='';const params:Record<string,string|number>={page:this.pagina,size:12};if(this.categoria)params['categoriaId']=this.categoria;this.http.get<Pagina<Prato>>(`${API_URL}/cardapio`,{params}).subscribe({next:r=>{this.pratos=r.content;this.totalPaginas=r.totalPages;this.carregando=false;this.cdr.detectChanges();},error:()=>{this.pratos=[];this.carregando=false;this.erro='Não foi possível conectar ao cardápio. Confirme se a API está em execução.';this.cdr.detectChanges();}});}
  filtrar(id:number|null){this.categoria=id;this.pagina=0;this.carregar();}
  mudarPagina(delta:number){this.pagina=Math.max(0,Math.min(this.totalPaginas-1,this.pagina+delta));this.carregar();}
  adicionar(p:Prato){this.cart.add(p);this.feedback.success(`${p.nome} adicionado à sacola.`);}
  verDetalhe(p:Prato){this.http.get<Prato>(`${API_URL}/cardapio/${p.id}`).subscribe({next:d=>this.pratoDetalhe=d,error:()=>this.pratoDetalhe=p});}
}

@Component({standalone:true,imports:[FormsModule,RouterLink],template:`
<div class="auth-layout"><div class="auth-aside"><span class="eyebrow">BOM E FIT · SUA PAUSA FAVORITA</span><h1>Um jeito mais gostoso de cuidar de você.</h1><p>Entre para acompanhar seus pedidos e descobrir novos sabores.</p><div class="auth-food">🥗</div></div><section class="auth-card"><a routerLink="/" class="back-link">← Voltar ao cardápio</a><div class="auth-tabs"><button type="button" [disabled]="enviando" [class.selected]="modo==='entrar'" (click)="modo='entrar';erro='';">Entrar</button><button type="button" [disabled]="enviando" [class.selected]="modo==='criar'" (click)="modo='criar';erro='';">Criar conta</button></div><h2>{{modo==='entrar'?'Boas-vindas de volta!':'Crie sua conta'}}</h2><p class="muted">{{modo==='entrar'?'Acesse sua conta para continuar.':'É rapidinho e sua próxima refeição já está mais perto.'}}</p>
<form class="auth-form" (ngSubmit)="enviar()">@if(modo==='criar'){<label>Nome completo<input name="nome" maxlength="120" required [(ngModel)]="nome" placeholder="Como podemos te chamar?"/></label><label>Telefone<input name="telefone" type="tel" maxlength="30" required [(ngModel)]="telefone" placeholder="(11) 99999-9999"/></label>}<label>E-mail<input name="email" type="email" maxlength="190" required [(ngModel)]="email" placeholder="voce@email.com"/></label><label>Senha<input name="senha" type="password" maxlength="72" [attr.minlength]="modo==='criar'?8:null" required [(ngModel)]="senha" placeholder="Mínimo 8 caracteres"/></label>@if(modo==='criar'){<label>Endereço de entrega<input name="endereco" maxlength="500" required [(ngModel)]="endereco" placeholder="Rua, número, bairro"/></label>}@if(erro){<div class="form-error">{{erro}}</div>}<button class="button primary full" type="submit" [disabled]="enviando">{{enviando?'Aguarde…':modo==='entrar'?'Entrar na minha conta':'Criar conta'}}</button></form><p class="auth-note">Ao continuar, você concorda com os termos de uso do Bom e Fit.</p></section></div>
`})
export class LoginPage {
 private auth=inject(AuthService);private router=inject(Router);modo:'entrar'|'criar'='entrar';nome='';email='';senha='';endereco='';telefone='';erro='';enviando=false;private route=inject(ActivatedRoute);private returnUrl=this.route.snapshot.queryParamMap.get('returnUrl');
 enviar(){this.erro='';if(!this.email.trim()||!this.senha.trim()||(this.modo==='criar'&&(!this.nome.trim()||!this.telefone.trim()||!this.endereco.trim()))){this.erro='Preencha todos os campos.';return;}this.enviando=true;const req=this.modo==='entrar'?this.auth.signIn(this.email,this.senha):this.auth.register({nome:this.nome,email:this.email,senha:this.senha,telefone:this.telefone,endereco:this.endereco});req.subscribe({next:r=>{if(this.modo==='criar'&&this.endereco.trim())sessionStorage.setItem('bomefit_checkout_address',this.endereco.trim());this.auth.save(r);this.enviando=false;const destino=r.usuario.perfil==='CLIENTE'&&this.returnUrl?.startsWith('/')&&!this.returnUrl.startsWith('//')?this.returnUrl:(r.usuario.perfil==='CLIENTE'?'/':'/admin');void this.router.navigateByUrl(destino);},error:e=>{this.enviando=false;this.erro=e.status===401?'E-mail ou senha inválidos.':e.error?.message||'Não foi possível entrar. Verifique os dados e tente novamente.';}});}
}

@Component({standalone:true,imports:[RouterLink,CurrencyPipe,FormsModule],template:`
<section class="cart-page"><a routerLink="/" class="back-link">← Continuar comprando</a><div class="section-heading"><div><span class="eyebrow">SUA SELEÇÃO</span><h2>Sacola</h2></div></div>@if(cart.items.length){<div class="cart-layout"><div class="cart-items">@for(i of cart.items;track i.prato.id){<article class="cart-row"><div class="cart-thumb">🥗</div><div class="cart-desc"><b>{{i.prato.nome}}</b><small>{{i.prato.categoria}}</small><span>{{i.prato.precoVenda|currency:'BRL'}}</span><label class="cart-note">Observações<input maxlength="500" [ngModel]="i.observacoes" (ngModelChange)="cart.setObservacoes(i.prato.id,$event)" placeholder="Ex.: sem cebola"/></label></div><div class="qty"><button (click)="cart.change(i.prato.id,-1)">−</button><b>{{i.quantidade}}</b><button (click)="cart.change(i.prato.id,1)">＋</button></div><strong>{{i.prato.precoVenda*i.quantidade|currency:'BRL'}}</strong></article>}</div><aside class="summary"><h3>Resumo do pedido</h3><div><span>Subtotal</span><b>{{cart.total|currency:'BRL'}}</b></div><div><span>Entrega</span><b class="green">A combinar</b></div><hr/><div class="summary-total"><span>Total</span><b>{{cart.total|currency:'BRL'}}</b></div><form class="checkout-form" (ngSubmit)="finalizar()"><label class="checkout-address">Endereço de entrega<textarea name="enderecoEntrega" rows="3" maxlength="500" required [(ngModel)]="enderecoEntrega" (ngModelChange)="persistirEndereco($event)" placeholder="Rua, número, bairro e complemento"></textarea></label><button type="submit" class="button primary full" [disabled]="enviando">{{enviando?'Enviando pedido…':'Finalizar pedido →'}}</button></form><small class="muted">Pagamento demonstrativo para fins acadêmicos.</small></aside></div>}@else{<div class="empty-state"><span>🛍️</span><h3>Sua sacola está esperando</h3><p>Adicione algo gostoso do nosso cardápio.</p><a routerLink="/" class="button primary">Ver cardápio</a></div>}</section>
`})
export class CartPage {
  cart=inject(CartService);auth=inject(AuthService);router=inject(Router);http=inject(HttpClient);feedback=inject(FeedbackService);
  enderecoEntrega=sessionStorage.getItem('bomefit_checkout_address')||'';enviando=false;
  persistirEndereco(value:string){this.enderecoEntrega=value;sessionStorage.setItem('bomefit_checkout_address',value);}
  finalizar(){
    if(!this.cart.items.length||this.enviando)return;
    const user=this.auth.user;
    if(!user){void this.router.navigate(['/entrar'],{queryParams:{returnUrl:'/carrinho'}});return;}
    if(user.perfil!=='CLIENTE'){this.feedback.error('Somente contas de cliente podem enviar pedidos.');return;}
    const endereco=this.enderecoEntrega.trim();
    if(!endereco){this.feedback.error('Informe o endereço para entrega.');return;}
    const body={enderecoEntrega:endereco,itens:this.cart.items.map(i=>({pratoId:i.prato.id,quantidade:i.quantidade,observacoes:i.observacoes||''}))};
    this.enviando=true;
    this.http.post<Pedido>(`${API_URL}/pedidos`,body).subscribe({next:()=>{this.enviando=false;this.cart.clear();this.feedback.success('Pedido recebido! Acompanhe o andamento na área Meus pedidos.');void this.router.navigate(['/pedidos']);},error:e=>{this.enviando=false;this.feedback.error(e.error?.message||'Não foi possível registrar o pedido. Verifique o cardápio e o estoque.');}});
  }
}

@Component({standalone:true,imports:[RouterLink,CurrencyPipe,DatePipe,FormsModule],template:`<section class="orders-page"><a routerLink="/" class="back-link">← Voltar ao cardápio</a><div class="section-heading"><div><span class="eyebrow">ACOMPANHE DE PERTO</span><h2>Meus pedidos</h2></div><button class="button outline" (click)="carregar()">↻ Atualizar</button></div>@if(erro){<div class="notice">{{erro}}</div>}@for(p of pedidos;track p.id){<article class="order-card"><div class="order-top"><div><small>PEDIDO #{{p.id}} · {{p.criadoEm|date:'dd/MM/yyyy HH:mm'}}</small><h3>{{p.status.replace('_',' ')}}</h3></div><b>{{p.valorTotal|currency:'BRL'}}</b></div><p>@for(i of p.itens;track $index){<span>{{i.quantidade}}× {{i.prato}} · </span>}</p><div class="order-progress"><span [class.done]="step(p.status)>=0">Recebido</span><span [class.done]="step(p.status)>=1">Confirmado</span><span [class.done]="step(p.status)>=2">Em preparo</span><span [class.done]="step(p.status)>=3">Pronto</span><span [class.done]="step(p.status)>=4">Saiu para entrega</span><span [class.done]="step(p.status)>=5">Finalizado</span></div>@if(['RECEBIDO','CONFIRMADO'].includes(p.status)){@if(cancelandoId===p.id){<form class="cancel-form" (ngSubmit)="cancelar(p.id)"><label>Motivo do cancelamento<input name="motivoCancelamento" maxlength="500" required [(ngModel)]="motivoCancelamento"/></label><button class="button outline" type="submit" [disabled]="!motivoCancelamento.trim()">Confirmar cancelamento</button><button class="text-button" type="button" (click)="cancelandoId=null;motivoCancelamento=''">Voltar</button></form>}@else{<button class="text-button" (click)="iniciarCancelamento(p.id)">Cancelar pedido</button>}}</article>}@if(totalPaginas>1){<div class="pagination"><button class="button outline" [disabled]="pagina<=0" (click)="mudarPagina(-1)">← Anterior</button><span>Página {{pagina+1}} de {{totalPaginas}}</span><button class="button outline" [disabled]="pagina+1>=totalPaginas" (click)="mudarPagina(1)">Próxima →</button></div>}@if(!pedidos.length&&!erro){<div class="empty-state"><span>🍽️</span><h3>Nenhum pedido por enquanto</h3><p>Quando fizer seu primeiro pedido, ele aparecerá aqui.</p><a routerLink="/" class="button primary">Escolher uma refeição</a></div>}</section>`})
export class OrdersPage implements OnInit, OnDestroy {
  http=inject(HttpClient);private cdr=inject(ChangeDetectorRef);feedback=inject(FeedbackService);pedidos:Pedido[]=[];erro='';pagina=0;totalPaginas=0;cancelandoId:number|null=null;motivoCancelamento='';private refreshTimer?:ReturnType<typeof setInterval>;
  ngOnInit(){this.carregar();this.refreshTimer=setInterval(()=>this.carregar(),15000);}
  ngOnDestroy(){if(this.refreshTimer)clearInterval(this.refreshTimer);}
  carregar(){this.http.get<Pagina<Pedido>>(`${API_URL}/pedidos/meus`,{params:{page:this.pagina,size:10}}).subscribe({next:r=>{this.pedidos=r.content;this.totalPaginas=r.totalPages;this.erro='';this.cdr.detectChanges();},error:()=>{this.erro='Não foi possível carregar seus pedidos.';this.cdr.detectChanges();}});}
  mudarPagina(delta:number){this.pagina=Math.max(0,Math.min(this.totalPaginas-1,this.pagina+delta));this.cancelandoId=null;this.motivoCancelamento='';this.carregar();}
  iniciarCancelamento(id:number){this.cancelandoId=id;this.motivoCancelamento='';}
  cancelar(id:number){const motivo=this.motivoCancelamento.trim();if(this.cancelandoId!==id||!motivo)return;this.http.patch<Pedido>(`${API_URL}/pedidos/${id}/cancelar`,{motivo}).subscribe({next:()=>{this.cancelandoId=null;this.motivoCancelamento='';this.feedback.success('Pedido cancelado.');this.carregar();},error:e=>this.feedback.error(e.error?.message||'Não foi possível cancelar.')});}
  step(s:string){return ['RECEBIDO','CONFIRMADO','EM_PREPARO','PRONTO','SAIU_ENTREGA','FINALIZADO'].indexOf(s);}
}

@Component({standalone:true,imports:[FormsModule,ReactiveFormsModule,CurrencyPipe,DatePipe,DecimalPipe],template:`
<div class="admin-layout"><aside class="admin-nav"><span class="eyebrow">PAINEL DE GESTÃO</span><h2>Bom<span>&fit</span></h2>@for(s of secoesVisiveis;track s.id){<button [class.current]="secao===s.id" (click)="abrir(s.id)"><span>{{s.icone}}</span>{{s.nome}}@if(s.id==='estoque'&&totalAlertas>0){<span class="nav-badge" [attr.aria-label]="totalAlertas+' ingredientes abaixo do mínimo'">{{totalAlertas}}</span>}</button>}<div class="admin-user">{{auth.user?.nome}}<small>{{auth.user?.perfil}}</small></div></aside><section class="admin-main"><div class="admin-heading"><div><span class="eyebrow">OPERAÇÃO</span><h1>{{titulo}}</h1></div><button class="button outline" (click)="carregar()">↻ Atualizar</button></div>
@if(['estoque','fornecedores','cardapio','categorias','compras','usuarios'].includes(secao)){<div class="pagination"><button class="button outline" [disabled]="(paginasAdmin[secao]||0)<=0" (click)="mudarPaginaLista(secao,-1)">← Anterior</button><span>Página {{(paginasAdmin[secao]||0)+1}} de {{totalPaginasLista(secao)||1}}</span><button class="button outline" [disabled]="(paginasAdmin[secao]||0)+1>=totalPaginasLista(secao)" (click)="mudarPaginaLista(secao,1)">Próxima →</button></div>}@if(secao==='estoque'){<div class="pagination"><span>Movimentações · página {{(paginasAdmin['movimentacoes']||0)+1}} de {{totalPaginasLista('movimentacoes')||1}}</span><button class="button outline" [disabled]="(paginasAdmin['movimentacoes']||0)<=0" (click)="mudarPaginaLista('movimentacoes',-1)">← Anterior</button><button class="button outline" [disabled]="(paginasAdmin['movimentacoes']||0)+1>=totalPaginasLista('movimentacoes')" (click)="mudarPaginaLista('movimentacoes',1)">Próxima →</button></div>}@if(erro){<div class="notice">{{erro}}</div>}@if(carregando){<div class="loading">Carregando…</div>}
@if(secao==='categorias'){<div class="panel"><h3>{{categoriaEditandoId?'Editar categoria':'Nova categoria'}}</h3><div class="form-grid"><label>Nome<input [(ngModel)]="formCategoria.nome" placeholder="Ex.: Saladas"/></label><label>Descrição<input [(ngModel)]="formCategoria.descricao" placeholder="Descrição curta"/></label><label>Ordem<input type="number" [(ngModel)]="formCategoria.ordem"/></label><button class="button primary" (click)="salvarCategoria()">{{categoriaEditandoId?'Salvar alterações':'Cadastrar categoria'}}</button>@if(categoriaEditandoId){<button class="button outline" (click)="cancelarEdicaoCategoria()">Cancelar</button>}</div></div>}
@if(secao==='cardapio'){<div class="panel"><h3>{{pratoEditandoId?'Editar prato':'Novo prato (começa inativo)'}}</h3><div class="form-grid"><label>Categoria<select [(ngModel)]="formPrato.categoriaId"><option [ngValue]="null">Selecione</option>@for(c of categoriasAdmin;track c.id){<option [ngValue]="c.id">{{c.nome}}</option>}</select></label><label>Nome<input [(ngModel)]="formPrato.nome"/></label><label>Descrição<input [(ngModel)]="formPrato.descricao"/></label><label>Foto (URL)<input [(ngModel)]="formPrato.fotoUrl"/></label><label>Status<select [(ngModel)]="formPrato.status"><option>INATIVO</option><option>ATIVO</option><option>PAUSADO</option></select></label><label>Preço<input type="number" step="0.01" [(ngModel)]="formPrato.precoVenda"/></label><label>Preparo (min)<input type="number" [(ngModel)]="formPrato.tempoPreparoMin"/></label><button class="button primary" (click)="salvarPrato()">{{pratoEditandoId?'Salvar prato':'Criar prato'}}</button>@if(pratoEditandoId){<button class="button outline" (click)="novoPrato()">Cancelar edição</button>}</div></div>@if(pratoSelecionado){<div class="panel"><h3>Ficha técnica do prato #{{pratoSelecionado}}</h3><form [formGroup]="fichaForm" (ngSubmit)="salvarFicha()"><label>Rendimento (porções)<input type="number" formControlName="rendimento" min="1"/></label><label>Modo de preparo<input formControlName="modoPreparo"/></label><div formArrayName="itens">@for(item of fichaItensForm.controls;track $index){<div class="form-grid" [formGroupName]="$index"><label>Ingrediente<select formControlName="ingredienteId"><option [ngValue]="null">Selecione</option>@for(i of ingredientesAdmin;track i.id){<option [ngValue]="i.id">{{i.nome}}</option>}</select></label><label>Quantidade<input type="number" step="0.001" formControlName="quantidade"/></label><label>Unidade<select formControlName="unidade"><option>G</option><option>ML</option><option>UN</option></select></label><label>Fator de correção<input type="number" step="0.001" min="1" formControlName="fatorCorrecao"/></label><button type="button" class="text-button" (click)="removerIngredienteFicha($index)">Remover ingrediente</button></div>}</div><button type="button" class="button outline" (click)="adicionarIngredienteFicha()">＋ Ingrediente</button><button type="submit" class="button primary" [disabled]="fichaForm.invalid">Salvar ficha técnica</button><button type="button" class="button outline" (click)="ativarPrato()">Ativar prato</button></form></div>}}
@if(secao==='estoque'){<div class="panel"><h3>{{ingredienteEditandoId?'Editar ingrediente':'Novo ingrediente'}}</h3><div class="form-grid"><label>Nome<input [(ngModel)]="formIngrediente.nome"/></label><label>SKU<input [(ngModel)]="formIngrediente.sku"/></label><label>Unidade<select [(ngModel)]="formIngrediente.unidadePadrao"><option>G</option><option>ML</option><option>UN</option><option>KG</option><option>L</option></select></label><label>Estoque mínimo<input type="number" [(ngModel)]="formIngrediente.estoqueMinimo"/></label><label>Custo unitário<input type="number" step="0.0001" [(ngModel)]="formIngrediente.custoUnitario"/></label><button class="button primary" (click)="salvarIngrediente()">{{ingredienteEditandoId?'Salvar ingrediente':'Cadastrar ingrediente'}}</button>@if(ingredienteEditandoId){<button class="button outline" (click)="cancelarEdicaoIngrediente()">Cancelar edição</button>}</div></div><div class="panel"><h3>Entrada manual de estoque</h3><div class="form-grid"><label>Ingrediente<select [(ngModel)]="formEntrada.ingredienteId"><option [ngValue]="null">Selecione</option>@for(a of ingredientesAdmin;track a.id){<option [ngValue]="a.id">{{a.nome}}</option>}</select></label><label>Quantidade<input type="number" step="0.001" [(ngModel)]="formEntrada.quantidade"/></label><label>Custo unitário<input type="number" step="0.0001" [(ngModel)]="formEntrada.custoUnitario"/></label><label>Lote<input [(ngModel)]="formEntrada.lote"/></label><label>Validade<input type="date" [(ngModel)]="formEntrada.validade"/></label><button class="button primary" (click)="registrarEntrada()">Registrar entrada</button></div></div><div class="panel"><h3>Registrar perda/saída</h3><div class="form-grid"><label>Ingrediente<select [(ngModel)]="formPerda.ingredienteId"><option [ngValue]="null">Selecione</option>@for(a of ingredientesAdmin;track a.id){<option [ngValue]="a.id">{{a.nome}}</option>}</select></label><label>Quantidade<input type="number" step="0.001" [(ngModel)]="formPerda.quantidade"/></label><label>Motivo<select [(ngModel)]="formPerda.motivo"><option>DESPERDICIO</option><option>VENCIMENTO</option><option>QUEBRA</option><option>USO_INTERNO</option></select></label><button class="button primary" (click)="registrarPerda()">Registrar saída</button></div></div>}
@if(secao==='estoque'){<div class="panel"><h3>Movimentações recentes</h3><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ingrediente</th><th>Tipo</th><th>Quantidade</th><th>Motivo</th><th>Lote / validade</th><th>Usuário</th></tr></thead><tbody>@for(m of movimentacoes;track m.id){<tr><td>{{m.data|date:'dd/MM/yyyy HH:mm'}}</td><td>{{m.ingrediente}}</td><td>{{m.tipo}}</td><td>{{m.quantidade}}</td><td>{{m.motivo}}</td><td>{{m.lote||'—'}} / {{m.validade? (m.validade|date:'dd/MM/yyyy'):'—'}}</td><td>{{m.usuario}}</td></tr>}</tbody></table></div></div>}
@if(secao==='fornecedores'){<div class="panel"><h3>{{fornecedorEditandoId?'Editar fornecedor':'Adicionar fornecedor'}}</h3><div class="form-grid"><label>Razão social<input [(ngModel)]="formFornecedor.razaoSocial"/></label><label>CNPJ<input [(ngModel)]="formFornecedor.cnpj" placeholder="14 dígitos"/></label><label>E-mail<input type="email" [(ngModel)]="formFornecedor.email"/></label><label>Telefone<input [(ngModel)]="formFornecedor.telefone"/></label><button class="button primary" (click)="salvarFornecedor()">{{fornecedorEditandoId?'Salvar fornecedor':'Cadastrar fornecedor'}}</button>@if(fornecedorEditandoId){<button class="button outline" (click)="fornecedorEditandoId=null;formFornecedor={razaoSocial:'',cnpj:'',email:'',telefone:''}">Cancelar</button>}</div></div>}
@if(secao==='fornecedores'){<div class="panel"><h3>Adicionar ingrediente ao catálogo</h3><div class="form-grid"><label>Fornecedor<select [(ngModel)]="formCatalogo.fornecedorId"><option [ngValue]="null">Selecione</option>@for(f of fornecedoresOpcoes;track f.id){<option [ngValue]="f.id">{{f.razaoSocial}}</option>}</select></label><label>Ingrediente<select [(ngModel)]="formCatalogo.ingredienteId"><option [ngValue]="null">Selecione</option>@for(i of ingredientesAdmin;track i.id){<option [ngValue]="i.id">{{i.nome}}</option>}</select></label><label>Preço na unidade vendida<input type="number" step="0.0001" [(ngModel)]="formCatalogo.preco"/></label><label>Unidade de venda<select [(ngModel)]="formCatalogo.unidadeVenda"><option>G</option><option>ML</option><option>UN</option><option>KG</option><option>L</option></select></label><button class="button primary" (click)="salvarCatalogo()">Salvar preço</button></div></div>}
@if(secao==='fornecedores'){<div class="panel"><h3>Comparar cotações</h3><div class="form-grid"><label>Ingrediente<select [(ngModel)]="ingredienteCotacaoId"><option [ngValue]="null">Selecione</option>@for(i of ingredientesAdmin;track i.id){<option [ngValue]="i.id">{{i.nome}}</option>}</select></label><button class="button outline" (click)="consultarCotacao()">Consultar preços</button></div>@if(cotacoes.length){<div class="table-wrap"><table><thead><tr><th>Fornecedor</th><th>CNPJ</th><th>Ingrediente</th><th>Preço</th><th>Unidade</th></tr></thead><tbody>@for(q of cotacoes;track q.fornecedorId){<tr><td>{{q.fornecedor}}</td><td>{{q.cnpj}}</td><td>{{q.ingrediente}}</td><td>{{q.preco|currency:'BRL'}}</td><td>{{q.unidadeVenda}}</td></tr>}</tbody></table></div>}@else if(cotacaoConsultada){<p class="muted">Nenhum fornecedor cadastrou preço para esse ingrediente.</p>}</div>}
@if(secao==='compras'){<div class="panel"><h3>Criar pedido de compra</h3><div class="form-grid"><label>Fornecedor<select [(ngModel)]="formCompra.fornecedorId"><option [ngValue]="null">Selecione</option>@for(f of fornecedoresOpcoes;track f.id){<option [ngValue]="f.id">{{f.razaoSocial}}</option>}</select></label>@for(item of itensCompra;track $index){<label>Ingrediente do catálogo<select [(ngModel)]="item.ingredienteId"><option [ngValue]="null">Selecione</option>@for(i of ingredientesAdmin;track i.id){<option [ngValue]="i.id">{{i.nome}}</option>}</select></label><label>Quantidade<input type="number" step="0.001" [(ngModel)]="item.quantidade"/></label><button class="text-button" (click)="removerItemCompra($index)" [disabled]="itensCompra.length===1">Remover item</button>}<button class="button outline" (click)="adicionarItemCompra()">＋ Item</button><button class="button primary" (click)="criarCompra()">Criar rascunho</button></div><small class="muted">O ingrediente precisa estar vinculado ao fornecedor no catálogo de preços.</small></div>}
@if(secao==='usuarios'&&auth.user?.perfil==='ADMIN'){<div class="panel"><h3>{{usuarioEditandoId?'Editar usuário interno':'Adicionar à equipe'}}</h3><div class="form-grid"><label>Nome<input [(ngModel)]="formUsuario.nome"/></label><label>E-mail<input type="email" [(ngModel)]="formUsuario.email"/></label><label>Senha inicial<input type="password" [(ngModel)]="formUsuario.senha"/></label><label>Perfil<select [(ngModel)]="formUsuario.perfil"><option value="GERENTE">Gerente</option><option value="COZINHEIRO">Cozinheiro</option></select></label><button class="button primary" (click)="criarUsuario()">{{usuarioEditandoId?'Salvar usuário':'Criar usuário'}}</button>@if(usuarioEditandoId){<button class="button outline" (click)="cancelarEdicaoUsuario()">Cancelar</button>}</div></div>}
@if(secao==='dashboard'){<div class="panel period-tools"><label>De<input type="date" [(ngModel)]="periodoInicio"/></label><label>Até<input type="date" [(ngModel)]="periodoFim"/></label><button class="button primary" (click)="carregarDashboard()">Aplicar período dos gráficos</button></div>@if(dashboard){<div class="metric-grid"><article><small>Pedidos hoje</small><b>{{dashboard.pedidosHoje}}</b><span>pedidos não cancelados</span></article><article><small>Faturamento hoje</small><b>{{dashboard.faturamentoHoje|currency:'BRL'}}</b><span>pedidos não cancelados</span></article><article><small>Ticket médio hoje</small><b>{{dashboard.ticketMedioHoje|currency:'BRL'}}</b><span>por pedido não cancelado</span></article><article><small>Food cost médio</small><b>{{dashboard.foodCostMedio|number:'1.1-1'}}%</b><span>pratos ativos do cardápio</span></article><article><small>Pedidos em preparo</small><b>{{dashboard.pedidosEmPreparo}}</b><span>na fila da cozinha</span></article></div><div class="panel chart-panel"><h3>Faturamento diário no período selecionado</h3><div class="chart-box"><canvas #salesChart aria-label="Gráfico de faturamento por dia"></canvas></div></div><div class="dashboard-columns"><div class="panel"><h3>Pratos mais vendidos no período</h3>@if(dashboard.pratosMaisVendidos.length){<div class="chart-box top-dishes-chart"><canvas #topDishesChart aria-label="Gráfico dos cinco pratos mais vendidos"></canvas></div><div class="table-wrap"><table><thead><tr><th>Prato</th><th>Unidades</th><th>Faturamento</th></tr></thead><tbody>@for(item of dashboard.pratosMaisVendidos;track item.pratoId){<tr><td>{{item.nome}}</td><td>{{item.unidadesVendidas}}</td><td>{{item.faturamento|currency:'BRL'}}</td></tr>}</tbody></table></div>}@else{<p class="muted">Ainda não há vendas no período.</p>}</div><div class="panel"><h3>Alertas de estoque · {{dashboard.alertasEstoque.length}}</h3>@if(dashboard.alertasEstoque.length){@for(a of dashboard.alertasEstoque;track a.id){<p class="alert-line">⚠ {{a.nome}} · {{a.saldo}} / mínimo {{a.estoqueMinimo}} {{a.unidadePadrao}}</p>}}@else{<p class="muted">Nenhum ingrediente abaixo do mínimo.</p>}</div></div>}<div class="panel"><h3>Pedidos recentes</h3><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Status</th><th>Valor</th><th>Ação</th></tr></thead><tbody>@for(p of pedidos;track p.id){<tr><td>#{{p.id}}</td><td>{{p.clienteNome}}</td><td><span class="status-pill">{{p.status.replace('_',' ')}}</span></td><td>{{p.valorTotal|currency:'BRL'}}</td><td><button class="text-button" (click)="avancar(p)">Avançar status</button></td></tr>}</tbody></table></div></div>}
@if(secao==='pedidos'){<div class="panel"><div class="panel-tools"><h3>Fila de pedidos</h3><div class="form-grid order-filters"><label>Status<select [(ngModel)]="filtroStatus"><option value="">Todos</option>@for(s of statusPedido;track s){<option [value]="s">{{s.replace('_',' ')}}</option>}</select></label><label>De<input type="date" [(ngModel)]="pedidoInicio"/></label><label>Até<input type="date" [(ngModel)]="pedidoFim"/></label><label>Canal<select [(ngModel)]="filtroCanal"><option value="">Todos</option><option value="WEB">Web</option></select></label><button class="button outline" (click)="aplicarFiltrosPedidos()">Filtrar</button></div></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Itens</th><th>Status</th><th>Total</th><th>Ações</th></tr></thead><tbody>@for(p of pedidos;track p.id){<tr><td>#{{p.id}}<small>{{p.criadoEm|date:'dd/MM HH:mm'}}</small></td><td>{{p.clienteNome}}</td><td>@for(i of p.itens;track $index){<small>{{i.quantidade}}× {{i.prato}}<br/></small>}</td><td><span class="status-pill">{{p.status.replace('_',' ')}}</span></td><td>{{p.valorTotal|currency:'BRL'}}</td><td><button class="text-button" (click)="verPedido(p)">Detalhes</button>@if(!['FINALIZADO','CANCELADO'].includes(p.status)){<button class="text-button" (click)="avancar(p)">Avançar →</button>}@if(['ADMIN','GERENTE'].includes(auth.user?.perfil||'')&&!['FINALIZADO','CANCELADO'].includes(p.status)){<button class="text-button" (click)="iniciarCancelamentoPedido(p.id)">Cancelar</button>}</td></tr>@if(pedidoDetalhe?.id===p.id){<tr><td colspan="6"><b>Entrega:</b> {{pedidoDetalhe.enderecoEntrega}} · <b>Pagamento:</b> {{pedidoDetalhe.statusPagamento}}<p>@for(h of pedidoDetalhe.timeline;track $index){<span>{{h.status}} · {{h.data|date:'dd/MM HH:mm'}} · {{h.usuario}}<br/></span>}</p></td></tr>}@if(pedidoCancelandoId===p.id){<tr><td colspan="6"><form class="cancel-form" (ngSubmit)="cancelarPedidoAdmin(p.id)"><label>Motivo do cancelamento<input name="motivoCancelamentoPedido" maxlength="500" required [(ngModel)]="motivoCancelamentoPedido"/></label><button class="button outline" type="submit" [disabled]="!motivoCancelamentoPedido.trim()">Confirmar cancelamento</button><button class="text-button" type="button" (click)="pedidoCancelandoId=null;motivoCancelamentoPedido=''">Voltar</button></form></td></tr>}}</tbody></table></div><div class="pagination"><button class="button outline" [disabled]="paginaPedidos<=0" (click)="mudarPaginaPedidos(-1)">← Anterior</button><span>Página {{paginaPedidos+1}} de {{totalPaginasPedidos||1}}</span><button class="button outline" [disabled]="paginaPedidos+1>=totalPaginasPedidos" (click)="mudarPaginaPedidos(1)">Próxima →</button></div></div>}
@if(secao==='estoque'){<div class="panel"><h3>Saldos e reposição</h3><div class="table-wrap"><table><thead><tr><th>Ingrediente</th><th>SKU</th><th>Saldo</th><th>Mínimo</th><th>Custo unitário</th><th>Estado</th><th>Ações</th></tr></thead><tbody>@for(a of estoque;track a.id){<tr><td>{{a.nome}}</td><td>{{a.sku}}</td><td>{{a.saldo}} {{a.unidadePadrao}}</td><td>{{a.estoqueMinimo}}</td><td>{{a.custoUnitario|currency:'BRL'}}</td><td><span class="status-pill" [class.warn]="baixo(a)">{{baixo(a)?'REPOR':'OK'}}</span></td><td><button class="text-button" (click)="editarIngrediente(a)">Editar</button><button class="text-button" (click)="desativarIngrediente(a)">Desativar</button></td></tr>}</tbody></table></div></div>}
@if(secao==='fornecedores'){<div class="panel"><h3>Fornecedores</h3><div class="table-wrap"><table><thead><tr><th>Razão social</th><th>CNPJ</th><th>E-mail</th><th>Telefone</th><th>Situação</th><th>Ações</th></tr></thead><tbody>@for(f of fornecedores;track f.id){<tr><td>{{f.razaoSocial}}</td><td>{{f.cnpj}}</td><td>{{f.email}}</td><td>{{f.telefone}}</td><td>{{f.status}}</td><td><button class="text-button" (click)="editarFornecedor(f)">Editar</button><button class="text-button" (click)="desativarFornecedor(f)">Desativar</button></td></tr>}</tbody></table></div><p class="muted">Cadastros e catálogo de preços são gerenciados pela API. Edite ou desative fornecedores e compare preços cadastrados no catálogo.</p></div>}
@if(secao==='cardapio'||secao==='categorias'){<div class="panel"><h3>{{secao==='cardapio'?'Pratos e fichas técnicas':'Categorias'}}</h3><div class="table-wrap"><table><thead><tr><th>Nome</th><th>{{secao==='cardapio'?'Categoria':'Descrição'}}</th><th>{{secao==='cardapio'?'Preço':'Ordem'}}</th>@if(secao==='cardapio'){<th>Custo / porção</th><th>Food cost</th>}<th>Status</th><th>Ações</th></tr></thead><tbody>@for(i of catalogo;track i.id){<tr><td>{{i.nome}}</td><td>{{i.categoria||i.descricao}}</td><td>{{secao==='cardapio'?(i.precoVenda|currency:'BRL'):i.ordem}}</td>@if(secao==='cardapio'){<td>{{i.custoPorPorcao?(i.custoPorPorcao|currency:'BRL'):'—'}}</td><td><span class="food-cost" [class.food-green]="i.faixa==='VERDE'" [class.food-yellow]="i.faixa==='AMARELO'" [class.food-red]="i.faixa==='VERMELHO'">{{i.foodCostPercentual!=null?(i.foodCostPercentual|number:'1.1-1')+'%':'—'}}</span></td>}<td>{{i.status}}</td><td>@if(secao==='cardapio'){<button class="text-button" (click)="editarPrato(i)">Editar / ficha</button><button class="text-button" (click)="alternarPrato(i)">{{i.status==='ATIVO'?'Desativar':'Ativar'}}</button>}@else{<button class="text-button" (click)="editarCategoria(i)">Editar</button><button class="text-button" (click)="desativarCategoria(i)">Desativar</button>}</td></tr>}</tbody></table></div><p class="muted">Edição, ativação e desativação respeitam os vínculos e regras do serviço de catálogo.</p></div>}
@if(secao==='compras'){<div class="panel"><h3>Pedidos de compra</h3><div class="table-wrap"><table><thead><tr><th>Nº</th><th>Fornecedor</th><th>Status</th><th>Total</th><th>Data</th><th>Ação</th></tr></thead><tbody>@for(c of compras;track c.id){<tr><td>#{{c.id}}</td><td>{{c.fornecedor}}</td><td>{{c.status}}</td><td>{{c.valorTotal|currency:'BRL'}}</td><td>{{c.criadaEm|date:'dd/MM/yyyy HH:mm'}}</td><td>@if(c.status==='RASCUNHO'){<button class="text-button" (click)="acaoCompra(c,'enviar')">Enviar</button>}@else if(c.status==='ENVIADO'){<button class="text-button" (click)="acaoCompra(c,'receber')">Receber</button><button class="text-button" (click)="acaoCompra(c,'cancelar')">Cancelar</button>}@else{<span class="muted">—</span>}</td></tr>}</tbody></table></div></div>}
@if(secao==='usuarios'){<div class="panel"><h3>Equipe</h3><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Ações</th></tr></thead><tbody>@for(u of usuarios;track u.id){<tr><td>{{u.nome}}</td><td>{{u.email}}</td><td>{{u.perfil}}</td><td>{{u.status}}</td><td><button class="text-button" (click)="editarUsuario(u)">Editar</button><button class="text-button" (click)="desativarUsuario(u)">Desativar</button></td></tr>}</tbody></table></div></div>}
</section></div>
`})
export class AdminPage implements OnInit, AfterViewInit, OnDestroy {
  http=inject(HttpClient);private cdr=inject(ChangeDetectorRef);feedback=inject(FeedbackService);auth=inject(AuthService);router=inject(Router);route=inject(ActivatedRoute);secao='dashboard';carregando=false;erro='';filtroStatus='';filtroCanal='';pedidoInicio='';pedidoFim='';paginaPedidos=0;totalPaginasPedidos=0;pedidoDetalhe:any=null;pedidoCancelandoId:number|null=null;motivoCancelamentoPedido='' ;statusPedido=['RECEBIDO','CONFIRMADO','EM_PREPARO','PRONTO','SAIU_ENTREGA','FINALIZADO','CANCELADO'];secoes=[{id:'dashboard',nome:'Visão geral',icone:'⌂'},{id:'pedidos',nome:'Pedidos',icone:'▤'},{id:'cardapio',nome:'Cardápio',icone:'◉'},{id:'categorias',nome:'Categorias',icone:'◫'},{id:'estoque',nome:'Estoque',icone:'▦'},{id:'fornecedores',nome:'Fornecedores',icone:'♧'},{id:'compras',nome:'Compras',icone:'▣'},{id:'usuarios',nome:'Equipe',icone:'♙'}];pedidos:Pedido[]=[];estoque:any[]=[];alertas:any[]=[];totalAlertas=0;fornecedores:any[]=[];catalogo:any[]=[];compras:any[]=[];cotacoes:any[]=[];ingredienteCotacaoId:number|null=null;cotacaoConsultada=false;usuarios:any[]=[];fornecedoresOpcoes:any[]=[];paginasAdmin:Record<string,number>={estoque:0,movimentacoes:0,fornecedores:0,cardapio:0,categorias:0,compras:0,usuarios:0};totaisAdmin:Record<string,number>={};
  private fb=inject(FormBuilder);formCategoria:any={nome:'',descricao:'',ordem:0};categoriaEditandoId:number|null=null;pratoEditandoId:number|null=null;ingredienteEditandoId:number|null=null;formIngrediente:any={nome:'',sku:'',unidadePadrao:'G',estoqueMinimo:0,custoUnitario:0};formEntrada:any={ingredienteId:null,quantidade:null,custoUnitario:null,lote:'',validade:null};formPerda:any={ingredienteId:null,quantidade:null,motivo:'DESPERDICIO'};formFornecedor:any={razaoSocial:'',cnpj:'',email:'',telefone:''};fornecedorEditandoId:number|null=null;usuarioEditandoId:number|null=null;formCompra:any={fornecedorId:null};itensCompra:any[]=[{ingredienteId:null,quantidade:1}];movimentacoes:any[]=[];formUsuario:any={nome:'',email:'',senha:'',perfil:'GERENTE'};formCatalogo:any={fornecedorId:null,ingredienteId:null,preco:null,unidadeVenda:'KG'};formPrato:any={categoriaId:null,nome:'',descricao:'',fotoUrl:'',precoVenda:null,tempoPreparoMin:15,status:'INATIVO'};pratoSelecionado:number|null=null;readonly fichaForm=this.fb.group({rendimento:[1,[Validators.required,Validators.min(1)]],modoPreparo:[''],itens:this.fb.array([this.novoItemFicha()])});get fichaItensForm():FormArray{return this.fichaForm.controls.itens;}categoriasAdmin:any[]=[];ingredientesAdmin:any[]=[];dashboard:Dashboard|null=null;periodoFim=this.dataInput(new Date());periodoInicio=this.dataInput(new Date(Date.now()-29*24*60*60*1000));private chart?:ChartInstance;private topDishesChart?:ChartInstance;private salesChartRender=0;private topDishesChartRender=0;
  @ViewChild('salesChart') set salesChartElement(element:ElementRef<HTMLCanvasElement>|undefined){this.chart?.destroy();this.chart=undefined;if(element&&this.dashboard)this.renderSalesChart(element.nativeElement);}
 constructor(){this.route.params.subscribe(p=>{this.secao=p['secao']||'dashboard';this.carregar();});}
 baixo(a:any){return Number(a.saldo)<Number(a.estoqueMinimo);} get secoesVisiveis(){const perfil=this.auth.user?.perfil;return this.secoes.filter(s=>perfil==='ADMIN'||(perfil==='GERENTE'&&s.id!=='usuarios')||(perfil==='COZINHEIRO'&&s.id==='pedidos'));} get titulo(){return this.secoes.find(s=>s.id===this.secao)?.nome||'Visão geral';}get valorPedidos(){return this.pedidos.reduce((a,p)=>a+p.valorTotal,0);}get totalPedidos(){return this.pedidos.length;}get emPreparo(){return this.pedidos.filter(p=>p.status==='EM_PREPARO').length;}
   ngOnInit(){} ngAfterViewInit(){} ngOnDestroy(){this.salesChartRender++;this.topDishesChartRender++;this.chart?.destroy();this.topDishesChart?.destroy();} abrir(s:string){void this.router.navigate(['/admin',...(s==='dashboard'?[]:[s])]);}
  private dataInput(date:Date){const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,10);}
  carregarDashboard(){this.carregando=true;this.http.get<Dashboard>(`${API_URL}/admin/dashboard`,{params:{inicio:this.periodoInicio,fim:this.periodoFim}}).subscribe({next:data=>{this.dashboard=data;this.carregando=false;this.cdr.detectChanges();setTimeout(()=>{const canvas=document.querySelector<HTMLCanvasElement>('[aria-label="Gráfico de faturamento por dia"]');if(canvas)this.renderSalesChart(canvas);const top=document.querySelector<HTMLCanvasElement>('[aria-label="Gráfico dos cinco pratos mais vendidos"]');if(top)this.renderTopDishesChart(top);},0);},error:e=>{this.carregando=false;this.mostrarErro(e);this.cdr.detectChanges();}});}
  private async renderSalesChart(canvas:HTMLCanvasElement){const renderId=++this.salesChartRender;const dashboard=this.dashboard;if(!dashboard)return;const {default:Chart}=await import('chart.js/auto');if(renderId!==this.salesChartRender||!canvas.isConnected||dashboard!==this.dashboard)return;this.chart?.destroy();this.chart=new Chart(canvas,{type:'line',data:{labels:dashboard.vendasDiarias.map(item=>item.data.slice(5)),datasets:[{label:'Faturamento diário',data:dashboard.vendasDiarias.map(item=>item.faturamento),borderColor:'#168443',backgroundColor:'rgba(22,132,67,.14)',fill:true,tension:.3,pointRadius:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:context=>` ${new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(context.parsed.y))}`}}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{callback:value=>new Intl.NumberFormat('pt-BR',{notation:'compact',style:'currency',currency:'BRL'}).format(Number(value))}}}}});}
  private async renderTopDishesChart(canvas:HTMLCanvasElement){const renderId=++this.topDishesChartRender;const dashboard=this.dashboard;if(!dashboard)return;const {default:Chart}=await import('chart.js/auto');if(renderId!==this.topDishesChartRender||!canvas.isConnected||dashboard!==this.dashboard)return;this.topDishesChart?.destroy();this.topDishesChart=new Chart(canvas,{type:'bar',data:{labels:dashboard.pratosMaisVendidos.map(item=>item.nome),datasets:[{label:'Unidades vendidas',data:dashboard.pratosMaisVendidos.map(item=>item.unidadesVendidas),backgroundColor:'#76b786',borderRadius:5}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{precision:0}},y:{grid:{display:false}}}}});}
  carregar(){
    this.carregando=true;this.erro='';
    if(['ADMIN','GERENTE'].includes(this.auth.user?.perfil||''))this.http.get<Pagina<any>>(`${API_URL}/admin/estoque/alertas`,{params:{page:0,size:1000}}).subscribe({next:r=>{this.alertas=r.content;this.totalAlertas=r.totalElements;this.cdr.detectChanges();},error:()=>{this.alertas=[];this.totalAlertas=0;this.cdr.detectChanges();}});else{this.alertas=[];this.totalAlertas=0;}
    if(this.secao==='dashboard')this.carregarDashboard();
    if(this.secao==='pedidos'||this.secao==='dashboard')this.carregarPedidos();
    const precisaIngredientes=['estoque','dashboard','compras','fornecedores','cardapio'].includes(this.secao);
    if(precisaIngredientes){
      this.http.get<Pagina<any>>(`${API_URL}/admin/ingredientes`,{params:{page:0,size:1000}}).subscribe({next:r=>{this.ingredientesAdmin=r.content.filter((i:any)=>i.status==='ATIVO');this.cdr.detectChanges();},error:()=>{}});
      if(this.secao==='estoque')this.http.get<Pagina<any>>(`${API_URL}/admin/estoque/saldo`,{params:this.paramsLista('estoque')}).subscribe({next:r=>{if(this.guardarPagina('estoque',r)){this.estoque=r.content;this.carregando=false;}this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar saldos de estoque.';this.cdr.detectChanges();}});
      if(this.secao==='dashboard'||this.secao==='compras'||this.secao==='fornecedores'||this.secao==='cardapio')this.http.get<Pagina<any>>(`${API_URL}/admin/estoque/saldo`,{params:{page:0,size:1000}}).subscribe({next:r=>{this.estoque=r.content;this.cdr.detectChanges();},error:()=>{}});
      if(this.secao==='estoque')this.http.get<Pagina<any>>(`${API_URL}/admin/estoque/movimentacoes`,{params:this.paramsLista('movimentacoes')}).subscribe({next:r=>{if(this.guardarPagina('movimentacoes',r))this.movimentacoes=r.content;this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar movimentações.';this.cdr.detectChanges();}});
    }
    if(this.secao==='fornecedores'||this.secao==='compras'){
      this.http.get<Pagina<any>>(`${API_URL}/admin/fornecedores`,{params:{page:0,size:1000}}).subscribe({next:r=>{this.fornecedoresOpcoes=r.content.filter((f:any)=>f.status==='ATIVO');this.cdr.detectChanges();},error:()=>{}});
      if(this.secao==='fornecedores')this.http.get<Pagina<any>>(`${API_URL}/admin/fornecedores`,{params:this.paramsLista('fornecedores')}).subscribe({next:r=>{if(this.guardarPagina('fornecedores',r)){this.fornecedores=r.content;this.carregando=false;}this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar fornecedores.';this.cdr.detectChanges();}});
    }
    if(this.secao==='cardapio'){
      this.http.get<Pagina<any>>(`${API_URL}/admin/pratos`,{params:{...this.paramsLista('cardapio'),sort:'id,desc'}}).subscribe({next:r=>{if(this.guardarPagina('cardapio',r)){this.catalogo=r.content;this.carregando=false;this.cdr.detectChanges();r.content.forEach(prato=>this.http.get<any>(`${API_URL}/admin/pratos/${prato.id}/custo`).subscribe({next:c=>{Object.assign(prato,c);this.cdr.detectChanges();},error:()=>{}}));}},error:()=>{this.carregando=false;this.erro='Falha ao carregar pratos.';}});
      this.http.get<Pagina<any>>(`${API_URL}/admin/categorias`,{params:{page:0,size:1000}}).subscribe({next:r=>{this.categoriasAdmin=r.content.filter((c:any)=>c.status==='ATIVO');this.cdr.detectChanges();},error:()=>{}});
    }
    if(this.secao==='categorias')this.http.get<Pagina<any>>(`${API_URL}/admin/categorias`,{params:this.paramsLista('categorias')}).subscribe({next:r=>{if(this.guardarPagina('categorias',r)){this.catalogo=r.content;this.carregando=false;}this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar categorias.';this.cdr.detectChanges();}});
    if(this.secao==='compras')this.http.get<Pagina<any>>(`${API_URL}/admin/compras`,{params:this.paramsLista('compras')}).subscribe({next:r=>{if(this.guardarPagina('compras',r)){this.compras=r.content;this.carregando=false;}this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar compras.';this.cdr.detectChanges();}});
    if(this.secao==='usuarios')this.http.get<Pagina<any>>(`${API_URL}/admin/usuarios`,{params:this.paramsLista('usuarios')}).subscribe({next:r=>{if(this.guardarPagina('usuarios',r)){this.usuarios=r.content;this.carregando=false;}this.cdr.detectChanges();},error:()=>{this.carregando=false;this.erro='Falha ao carregar usuários.';this.cdr.detectChanges();}});
  }  private paramsLista(chave:string){return {page:this.paginasAdmin[chave]||0,size:10};}
  totalPaginasLista(chave:string){return this.totaisAdmin[chave]||0;}
  private guardarPagina(chave:string,r:Pagina<any>){this.totaisAdmin[chave]=r.totalPages;if(r.totalPages>0&&(this.paginasAdmin[chave]||0)>=r.totalPages){this.paginasAdmin[chave]=r.totalPages-1;this.carregar();return false;}return true;}
  mudarPaginaLista(chave:string,delta:number){const paginas=this.totalPaginasLista(chave);if(!paginas)return;this.paginasAdmin[chave]=Math.max(0,Math.min(paginas-1,(this.paginasAdmin[chave]||0)+delta));this.carregar();}
  private carregarPedidos(){const params:Record<string,string|number>={page:this.secao==='dashboard'?0:this.paginaPedidos,size:this.secao==='dashboard'?5:10};if(this.secao==='pedidos'){if(this.filtroStatus)params['status']=this.filtroStatus;if(this.filtroCanal)params['canal']=this.filtroCanal;if(this.pedidoInicio)params['inicio']=this.pedidoInicio;if(this.pedidoFim)params['fim']=this.pedidoFim;}this.http.get<Pagina<Pedido>>(`${API_URL}/pedidos/admin`,{params}).subscribe({next:r=>{this.pedidos=r.content;this.totalPaginasPedidos=r.totalPages;this.carregando=false;this.cdr.detectChanges();},error:()=>{this.pedidos=[];this.carregando=false;this.erro='Não foi possível carregar os pedidos. Confira a API e suas permissões.';this.cdr.detectChanges();}});}
  aplicarFiltrosPedidos(){this.paginaPedidos=0;this.pedidoDetalhe=null;this.pedidoCancelandoId=null;this.motivoCancelamentoPedido='';this.carregarPedidos();}
  mudarPaginaPedidos(delta:number){this.paginaPedidos=Math.max(0,Math.min(this.totalPaginasPedidos-1,this.paginaPedidos+delta));this.pedidoCancelandoId=null;this.motivoCancelamentoPedido='';this.carregarPedidos();}
  iniciarCancelamentoPedido(id:number){this.pedidoCancelandoId=id;this.motivoCancelamentoPedido='';}
  cancelarPedidoAdmin(id:number){const motivo=this.motivoCancelamentoPedido.trim();if(this.pedidoCancelandoId!==id||!motivo)return;this.http.patch<Pedido>(`${API_URL}/pedidos/${id}/cancelar`,{motivo}).subscribe({next:()=>{this.pedidoCancelandoId=null;this.motivoCancelamentoPedido='';this.feedback.success(`Pedido #${id} cancelado e estoque estornado quando aplicável.`);this.carregarPedidos();},error:e=>this.feedback.error(e.error?.message||'Não foi possível cancelar o pedido.')});}
  verPedido(p:Pedido){this.pedidoDetalhe=this.pedidoDetalhe?.id===p.id?null:p;}
  salvarCategoria(){const req=this.categoriaEditandoId?this.http.put(`${API_URL}/admin/categorias/${this.categoriaEditandoId}`,this.formCategoria):this.http.post(`${API_URL}/admin/categorias`,this.formCategoria);req.subscribe({next:()=>{this.feedback.success('Categoria salva.');this.formCategoria={nome:'',descricao:'',ordem:0};this.categoriaEditandoId=null;this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  editarCategoria(c:any){this.categoriaEditandoId=c.id;this.formCategoria={nome:c.nome,descricao:c.descricao||'',ordem:c.ordem};}
  cancelarEdicaoCategoria(){this.categoriaEditandoId=null;this.formCategoria={nome:'',descricao:'',ordem:0};}
  desativarCategoria(c:any){if(!confirm(`Desativar a categoria ${c.nome}?`))return;this.http.delete(`${API_URL}/admin/categorias/${c.id}`).subscribe({next:()=>{this.feedback.success('Categoria desativada.');this.carregar();},error:e=>this.mostrarErro(e)});}
  alternarPrato(p:any){if(p.status==='ATIVO'){this.http.delete(`${API_URL}/admin/pratos/${p.id}`).subscribe({next:()=>{this.feedback.success('Prato desativado.');this.carregar();},error:e=>this.mostrarErro(e)});return;}const categoriaId=this.categoriasAdmin.find(c=>c.nome===p.categoria)?.id;if(!categoriaId){this.feedback.error('A categoria deste prato está inativa. Edite o prato e escolha uma categoria ativa antes de reativá-lo.');return;}this.http.put(`${API_URL}/admin/pratos/${p.id}`,{categoriaId,nome:p.nome,descricao:p.descricao,fotoUrl:p.fotoUrl,precoVenda:p.precoVenda,tempoPreparoMin:p.tempoPreparoMin,status:'ATIVO'}).subscribe({next:()=>{this.feedback.success('Prato ativado.');this.carregar();},error:e=>this.mostrarErro(e)});}
  novoItemFicha(item:any={}){return this.fb.group({ingredienteId:[item.ingredienteId??null,Validators.required],quantidade:[item.quantidade??null,[Validators.required,Validators.min(0.001)]],unidade:[item.unidade??'G',Validators.required],fatorCorrecao:[item.fatorCorrecao??1,[Validators.required,Validators.min(1)]]});}
  editarPrato(p:any){this.pratoEditandoId=p.id;this.pratoSelecionado=p.id;this.formPrato={categoriaId:this.categoriasAdmin.find(c=>c.nome===p.categoria)?.id??null,nome:p.nome,descricao:p.descricao,fotoUrl:p.fotoUrl||'',precoVenda:p.precoVenda,tempoPreparoMin:p.tempoPreparoMin,status:p.status};this.http.get<any>(`${API_URL}/admin/pratos/${p.id}/ficha`).subscribe({next:f=>{this.fichaForm.patchValue({rendimento:f.rendimento,modoPreparo:f.modoPreparo||''});this.fichaItensForm.clear();(f.itens.length?f.itens:[{}]).forEach((x:any)=>this.fichaItensForm.push(this.novoItemFicha(x)));},error:e=>this.mostrarErro(e)});}
  novoPrato(){this.pratoEditandoId=null;this.pratoSelecionado=null;this.formPrato={categoriaId:null,nome:'',descricao:'',fotoUrl:'',precoVenda:null,tempoPreparoMin:15,status:'INATIVO'};}
  salvarIngrediente(){const req=this.ingredienteEditandoId?this.http.put(`${API_URL}/admin/ingredientes/${this.ingredienteEditandoId}`,this.formIngrediente):this.http.post(`${API_URL}/admin/ingredientes`,this.formIngrediente);req.subscribe({next:()=>{this.feedback.success(this.ingredienteEditandoId?'Ingrediente atualizado.':'Ingrediente cadastrado.');this.cancelarEdicaoIngrediente();this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  editarIngrediente(i:any){this.ingredienteEditandoId=i.id;this.formIngrediente={nome:i.nome,sku:i.sku,unidadePadrao:i.unidadePadrao,estoqueMinimo:i.estoqueMinimo,custoUnitario:i.custoUnitario};}
  cancelarEdicaoIngrediente(){this.ingredienteEditandoId=null;this.formIngrediente={nome:'',sku:'',unidadePadrao:'G',estoqueMinimo:0,custoUnitario:0};}
  desativarIngrediente(i:any){if(!confirm(`Desativar o ingrediente ${i.nome}?`))return;this.http.delete(`${API_URL}/admin/ingredientes/${i.id}`).subscribe({next:()=>{this.feedback.success('Ingrediente desativado.');this.carregar();},error:e=>this.mostrarErro(e)});}
  registrarEntrada(){this.http.post(`${API_URL}/admin/estoque/entrada-manual`,this.formEntrada).subscribe({next:()=>{this.feedback.success('Entrada de estoque registrada.');this.formEntrada={ingredienteId:null,quantidade:null,custoUnitario:null,lote:'',validade:null};this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  registrarPerda(){this.http.post(`${API_URL}/admin/estoque/movimentacao`,this.formPerda).subscribe({next:()=>{this.feedback.success('Saída de estoque registrada.');this.formPerda={ingredienteId:null,quantidade:null,motivo:'DESPERDICIO'};this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  salvarFornecedor(){const req=this.fornecedorEditandoId?this.http.put(`${API_URL}/admin/fornecedores/${this.fornecedorEditandoId}`,this.formFornecedor):this.http.post(`${API_URL}/admin/fornecedores`,this.formFornecedor);req.subscribe({next:()=>{this.feedback.success('Fornecedor salvo.');this.formFornecedor={razaoSocial:'',cnpj:'',email:'',telefone:''};this.fornecedorEditandoId=null;this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  consultarCotacao(){if(!this.ingredienteCotacaoId)return;this.cotacaoConsultada=true;this.http.get<any[]>(`${API_URL}/admin/fornecedores/cotacao/${this.ingredienteCotacaoId}`).subscribe({next:r=>this.cotacoes=r,error:e=>this.mostrarErro(e)});}
  editarFornecedor(f:any){this.fornecedorEditandoId=f.id;this.formFornecedor={razaoSocial:f.razaoSocial,cnpj:f.cnpj,email:f.email||'',telefone:f.telefone||''};}
  desativarFornecedor(f:any){if(!confirm(`Desativar o fornecedor ${f.razaoSocial}?`))return;this.http.delete(`${API_URL}/admin/fornecedores/${f.id}`).subscribe({next:()=>{this.feedback.success('Fornecedor desativado.');this.carregar();},error:e=>this.mostrarErro(e)});}
  editarUsuario(u:any){this.usuarioEditandoId=u.id;this.formUsuario={nome:u.nome,email:u.email,senha:'',perfil:u.perfil,telefone:u.telefone||'',endereco:u.endereco||''};}
  cancelarEdicaoUsuario(){this.usuarioEditandoId=null;this.formUsuario={nome:'',email:'',senha:'',perfil:'GERENTE'};}
  desativarUsuario(u:any){if(!confirm(`Desativar ${u.nome}?`))return;this.http.delete(`${API_URL}/admin/usuarios/${u.id}`).subscribe({next:()=>{this.feedback.success('Usuário desativado.');this.carregar();},error:e=>this.mostrarErro(e)});}
  salvarCatalogo(){this.http.put(`${API_URL}/admin/fornecedores/${this.formCatalogo.fornecedorId}/catalogo`,{ingredienteId:this.formCatalogo.ingredienteId,preco:this.formCatalogo.preco,unidadeVenda:this.formCatalogo.unidadeVenda}).subscribe({next:()=>this.feedback.success('Preço adicionado ao catálogo.'),error:(e:any)=>this.mostrarErro(e)});}
  adicionarItemCompra(){this.itensCompra=[...this.itensCompra,{ingredienteId:null,quantidade:1}];}
  removerItemCompra(index:number){if(this.itensCompra.length>1)this.itensCompra=this.itensCompra.filter((_,i)=>i!==index);}
  criarCompra(){this.http.post(`${API_URL}/admin/compras`,{fornecedorId:this.formCompra.fornecedorId,itens:this.itensCompra}).subscribe({next:()=>{this.feedback.success('Rascunho de compra criado.');this.formCompra={fornecedorId:null};this.itensCompra=[{ingredienteId:null,quantidade:1}];this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  criarUsuario(){const body={...this.formUsuario};if(this.usuarioEditandoId&&!body.senha)delete body.senha;const req=this.usuarioEditandoId?this.http.put(`${API_URL}/admin/usuarios/${this.usuarioEditandoId}`,body):this.http.post(`${API_URL}/admin/usuarios`,body);req.subscribe({next:()=>{this.feedback.success('Usuário salvo.');this.cancelarEdicaoUsuario();this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  salvarPrato(){const criando=!this.pratoEditandoId;const req=this.pratoEditandoId?this.http.put<any>(`${API_URL}/admin/pratos/${this.pratoEditandoId}`,this.formPrato):this.http.post<any>(`${API_URL}/admin/pratos`,{...this.formPrato,status:'INATIVO'});req.subscribe({next:r=>{this.feedback.success('Prato salvo.');this.pratoSelecionado=r.id;this.pratoEditandoId=r.id;if(criando)this.paginasAdmin['cardapio']=0;this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  adicionarIngredienteFicha(){this.fichaItensForm.push(this.novoItemFicha());}
  removerIngredienteFicha(index:number){if(this.fichaItensForm.length>1)this.fichaItensForm.removeAt(index);}
  salvarFicha(){if(!this.pratoSelecionado||this.fichaForm.invalid)return;this.http.put(`${API_URL}/admin/pratos/${this.pratoSelecionado}/ficha`,this.fichaForm.getRawValue()).subscribe({next:()=>this.feedback.success('Ficha técnica salva.'),error:(e:any)=>this.mostrarErro(e)});}
  ativarPrato(){if(!this.pratoSelecionado)return;this.http.put(`${API_URL}/admin/pratos/${this.pratoSelecionado}`,{...this.formPrato,status:'ATIVO'}).subscribe({next:()=>{this.feedback.success('Prato ativado no cardápio.');this.pratoSelecionado=null;this.carregar();},error:(e:any)=>this.mostrarErro(e)});}
  mostrarErro(e:any){this.erro=e.error?.message||'Não foi possível concluir a operação. Revise os dados e tente novamente.';this.feedback.error(this.erro);}
 avancar(p:Pedido){const i=this.statusPedido.indexOf(p.status);const next=this.statusPedido[i+1];if(!next||next==='CANCELADO')return;this.http.patch(`${API_URL}/pedidos/${p.id}/status`,{status:next}).subscribe({next:()=>{this.feedback.success(`Pedido #${p.id} atualizado para ${next.replace('_',' ')}.`);this.carregar();},error:e=>this.feedback.error(e.error?.message||'Não foi possível avançar o pedido.')});}
 acaoCompra(c:any,acao:'enviar'|'receber'|'cancelar'){if(acao==='cancelar'&&!confirm(`Cancelar a compra #${c.id}?`))return;const method=acao==='receber'?'post':'patch';(this.http as any)[method](`${API_URL}/admin/compras/${c.id}/${acao}`,{}).subscribe({next:()=>{this.feedback.success(acao==='enviar'?'Compra enviada ao fornecedor.':acao==='receber'?'Compra recebida e estoque atualizado.':'Compra cancelada.');this.carregar();},error:(e:any)=>this.feedback.error(e.error?.message||'Não foi possível atualizar a compra.')});}
}










